{"code": "def run(inputs: dict) -> dict:
    import csv
    import io

    # 1. Извлекаем денежные средства за FY 2024 и FY 2025
    metrics = inputs.get("ExtractedMetric", [])
    cash_2024 = None
    cash_2025 = None

    for m in metrics:
        if m.get("concept") != "Денежные средства и денежные эквиваленты":
            continue
        period = m.get("period_ref")
        value = m["scalar_fact"]["value"]
        unit = m["scalar_fact"]["unit"]
        if unit != "млн. руб.":
            raise ValueError(f"Ожидалась единица 'млн. руб.', получена '{unit}'")
        if period == "FY 2024":
            if cash_2024 is not None and cash_2024 != value:
                raise ValueError("Противоречивые значения денежных средств за FY 2024")
            cash_2024 = value
        elif period == "FY 2025":
            if cash_2025 is not None and cash_2025 != value:
                raise ValueError("Противоречивые значения денежных средств за FY 2025")
            cash_2025 = value

    if cash_2024 is None:
        raise ValueError("Не найдены денежные средства за FY 2024")
    if cash_2025 is None:
        raise ValueError("Не найдены денежные средства за FY 2025")

    # 2. Извлекаем цены Brent из CSV
    brent_artifacts = inputs.get("dyn:brent_csv", [])
    if not brent_artifacts:
        raise ValueError("Не предоставлен dyn:brent_csv")
    brent_text = brent_artifacts[0]["payload"]["text"]

    brent_2024 = None
    brent_2025 = None
    reader = csv.DictReader(io.StringIO(brent_text))
    for row in reader:
        date = row.get("Date", "").strip()
        price_str = row.get("Price", "").strip()
        if not date or not price_str:
            continue
        try:
            price = float(price_str)
        except ValueError:
            continue
        if date == "2024-06-30":
            brent_2024 = price
        elif date == "2025-06-30":
            brent_2025 = price

    if brent_2024 is None:
        raise ValueError("Не найдена цена Brent на 2024-06-30")
    if brent_2025 is None:
        raise ValueError("Не найдена цена Brent на 2025-06-30")

    # 3. Рассчитываем процентные изменения
    cash_change_pct = ((cash_2025 - cash_2024) / cash_2024) * 100
    brent_change_pct = ((brent_2025 - brent_2024) / brent_2024) * 100

    return {
        "cash_fy_2024_mln_rub": cash_2024,
        "cash_fy_2025_mln_rub": cash_2025,
        "brent_2024_usd_per_bbl": brent_2024,
        "brent_2025_usd_per_bbl": brent_2025,
        "cash_change_pct": cash_change_pct,
        "brent_change_pct": brent_change_pct,
    }
